effect.shader:
vec2 hash2(vec2 c) {
    c = vec2(
        dot(c, vec2(127.1, 311.7)),
        dot(c, vec2(269.5, 183.3))
    ) + vec2(seed * 13.7);
    return fract(sin(c) * 43758.5453);
}

float hash1(vec2 c) {
    return fract(sin(dot(c, vec2(419.2, 371.9)) + seed * 13.7) * 9999.9);
}

/**
 * As duas menores distâncias (F1, F2) e a célula dona do pixel. Olha as 9 células
 * da vizinhança 3×3: a ingênua olharia TODAS, esta prende a conta no grid.
 */
vec3 voronoi(vec2 p, float t) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    float f1 = 9.0;
    float f2 = 9.0;
    vec2 donaDoPixel = vec2(0.0);

    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 vizinha = vec2(float(x), float(y));
            vec2 h = hash2(i + vizinha);
            // O ponto da célula anima no círculo: `sin/cos` do tempo mantém o movimento preso dentro dela.
            vec2 ponto = vizinha + 0.5 + (h - 0.5) * jitter + 0.35 * jitter * vec2(
                sin(t + h.x * 6.2831),
                cos(t + h.y * 6.2831)
            );
            float d = length(ponto - f);
            if (d < f1) {
                f2 = f1;
                f1 = d;
                donaDoPixel = i + vizinha;
            } else if (d < f2) {
                f2 = d;
            }
        }
    }
    return vec3(f1, f2, hash1(donaDoPixel));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y) * density;
    vec3 v = voronoi(p, acTime * speed);

    float f1 = v.x;
    float f2 = v.y;
    float idDaCelula = v.z;

    // A borda aparece onde F2 − F1 é pequeno: ali duas células disputam o pixel.
    float dif = f2 - f1;
    float borda = 1.0 - smoothstep(edgeWidth * 0.5, edgeWidth, dif);

    // Cor da célula: ou a cor base, ou uma tingida pelo id (shift de matiz).
    vec3 corBase = cellColor.rgb;
    vec3 corTingida = corBase * (0.5 + idDaCelula);
    vec3 corDaCelula = mix(corBase, corTingida, colorByCell);

    // Um gradiente dentro da célula (mais escuro perto da borda): barato e dá relevo.
    float sombra = 1.0 - smoothstep(0.0, 0.6, f1);

    vec3 corDoPadrao = mix(corDaCelula * (0.55 + 0.45 * sombra), edgeColor.rgb, borda);
    float alfaDoPadrao = mix(cellColor.a, edgeColor.a, borda);

    vec3 cor = mix(original.rgb, corDoPadrao, blend * alfaDoPadrao);
    float alfa = mix(original.a, max(original.a, alfaDoPadrao), blend);

    fragColor = vec4(cor, alfa);
}
